package lsrefs

import (
	"context"
	"fmt"
	"io"
	"strings"

	"github.com/go-git/go-git/v6/plumbing/format/pktline"
)

// WriteRef encodes one Ref as a v2 ls-refs response pktline and writes
// it to w. Refs that don't pass the request's prefix filter produce no
// output (returns nil). Used by the streaming Handle path and by the
// slice-based EncodeResponse helper.
//
// The encoder follows gitprotocol-v2's grammar:
//
//	ref = PKT-LINE(obj-id-or-unborn SP refname *(SP ref-attribute) LF)
//	ref-attribute = (symref | peeled | entire-maximal)
//
// Symref, peeled and entire-maximal attributes are emitted only when the
// request opted in;
// the unborn obj-id form is emitted only when both the request advertised
// `unborn` and the ref itself is flagged Unborn.
func WriteRef(w io.Writer, req *Request, r Ref) error {
	if !req.Match(r.Name.String()) {
		return nil
	}
	line, err := formatRef(req, r)
	if err != nil {
		return err
	}
	if _, err := pktline.Writef(w, "%s\n", line); err != nil {
		return fmt.Errorf("lsrefs: write ref %s: %w", r.Name, err)
	}
	return nil
}

// WriteFlush writes the section-terminating flush packet expected at the
// end of an ls-refs response, after the last (or zeroth) WriteRef.
func WriteFlush(w io.Writer) error {
	if err := pktline.WriteFlush(w); err != nil {
		return fmt.Errorf("lsrefs: write flush: %w", err)
	}
	return nil
}

// EncodeResponse is a slice-form convenience over WriteRef + WriteFlush.
// Kept so tests and library users with an already-materialised slice
// don't have to construct a callback. The handler does NOT use this
// path — it streams through RefSource's emit callback instead.
func EncodeResponse(ctx context.Context, w io.Writer, req *Request, refs []Ref) error {
	for _, r := range refs {
		if err := ctx.Err(); err != nil {
			return fmt.Errorf("lsrefs: encode cancelled: %w", err)
		}
		if err := WriteRef(w, req, r); err != nil {
			return err
		}
	}
	if err := ctx.Err(); err != nil {
		return fmt.Errorf("lsrefs: encode cancelled: %w", err)
	}
	return WriteFlush(w)
}

func formatRef(req *Request, r Ref) (string, error) {
	var sb strings.Builder
	switch {
	case r.Unborn:
		if !req.Unborn {
			return "", fmt.Errorf("lsrefs: ref %s is unborn but client did not request unborn", r.Name)
		}
		sb.WriteString("unborn")
	default:
		sb.WriteString(r.Hash.String())
	}
	sb.WriteByte(' ')
	sb.WriteString(r.Name.String())
	if req.Symrefs && r.Target != "" {
		sb.WriteString(" symref-target:")
		sb.WriteString(r.Target.String())
	}
	if req.Peel && !r.Peeled.IsZero() {
		sb.WriteString(" peeled:")
		sb.WriteString(r.Peeled.String())
	}
	if req.Maximal && r.Maximal {
		sb.WriteByte(' ')
		sb.WriteString(MaximalFeature)
	}
	return sb.String(), nil
}
