package lsrefs

import (
	"context"
	"errors"
	"fmt"
	"io"
	"strings"

	"github.com/go-git/go-git/v6/plumbing/format/pktline"
)

// maxRefPrefixes caps the number of `ref-prefix` arguments the
// decoder will accept in a single request. Matches upstream Git's
// TOO_MANY_PREFIXES at ls-refs.c:48 so the prefix-overflow recovery
// path produces the same set of refs.
const maxRefPrefixes = 65536

// Request is a decoded ls-refs request.
//
// Symrefs, Peel and Unborn correspond to the three boolean flag arguments;
// RefPrefixes is the (possibly empty) set of `ref-prefix <prefix>` filters.
// An empty RefPrefixes means "advertise all refs"; per spec each prefix is
// an inclusive filter and a ref matches if it starts with any one of them.
// Maximal is the MaximalFeature extension argument.
type Request struct {
	Symrefs     bool
	Peel        bool
	Unborn      bool
	Maximal     bool
	RefPrefixes []string
}

// Match reports whether name passes the request's ref-prefix filter.
// An empty RefPrefixes matches everything (per gitprotocol-v2).
func (r *Request) Match(name string) bool {
	if len(r.RefPrefixes) == 0 {
		return true
	}
	for _, p := range r.RefPrefixes {
		if strings.HasPrefix(name, p) {
			return true
		}
	}
	return false
}

// DecodeRequest reads ls-refs arguments from r until a flush packet.
// ctx is checked at every pktline boundary so a slow or hostile sender
// can be aborted by the caller.
//
// The body shape per gitprotocol-v2 is:
//
//	[capability lines] [delim] [argument lines] flush
//
// AT MOST one delim is allowed (between capabilities and arguments).
// A second delim or any non-flush terminator triggers upstream's
// "expected flush after ls-refs arguments" error (ls-refs.c:191-192).
func DecodeRequest(ctx context.Context, r io.Reader) (*Request, error) {
	req := &Request{}
	var sawDelim bool
	for {
		if err := ctx.Err(); err != nil {
			return nil, fmt.Errorf("lsrefs: decode cancelled: %w", err)
		}
		l, payload, err := pktline.ReadLine(r)
		if err != nil {
			return nil, fmt.Errorf("lsrefs: read pktline: %w", err)
		}
		switch l {
		case pktline.Flush:
			// Upstream's "cap reached → clear list" recovery
			// (ls-refs.c:199-201). Once the prefix list hits the
			// cap, treat it as "no filter" — returning all refs is
			// better than truncating to an arbitrary 65536-sized
			// window. With the parse-time drop above the count
			// never exceeds the cap, so the >= check is equivalent
			// to == cap.
			if len(req.RefPrefixes) >= maxRefPrefixes {
				req.RefPrefixes = nil
			}
			return req, nil
		case pktline.Delim:
			// Capabilities/arguments separator. Exactly one is
			// allowed; a second triggers upstream's strict-flush
			// check (ls-refs.c:191-192).
			if sawDelim {
				return nil, errors.New("lsrefs: expected flush after ls-refs arguments")
			}
			sawDelim = true
			continue
		}
		line := strings.TrimRight(string(payload), "\n")
		switch {
		// Capability lines emitted by upstream's send_capabilities
		// path before the delim packet (see git/fetch-pack.c). The
		// ls-refs command doesn't consume any of them, but we accept
		// the prefixes so spec-compliant clients aren't rejected for
		// sending capabilities the dispatcher would normally absorb.
		case strings.HasPrefix(line, "agent="),
			strings.HasPrefix(line, "session-id="),
			strings.HasPrefix(line, "server-option="),
			strings.HasPrefix(line, "object-format="):
			// no-op on the ls-refs command

		case line == "symrefs":
			req.Symrefs = true
		case line == "peel":
			req.Peel = true
		case line == "unborn":
			req.Unborn = true
		case line == MaximalFeature:
			// Accepted even while the server does not advertise it. HTTP v2
			// is stateless, so during a rolling deploy the capability
			// request and the ls-refs request can reach different nodes.
			// Every node must accept the argument before any node
			// advertises it.
			req.Maximal = true
		case strings.HasPrefix(line, "ref-prefix "):
			// Match upstream's graceful-degradation: silently drop
			// additional prefixes once the cap is hit
			// (ls-refs.c:182-184). The post-loop clear below then
			// turns "cap reached" into "no filter" so a runaway
			// prefix list returns ALL refs instead of an arbitrary
			// 65536-sized window.
			if len(req.RefPrefixes) < maxRefPrefixes {
				req.RefPrefixes = append(req.RefPrefixes, strings.TrimPrefix(line, "ref-prefix "))
			}
		default:
			// Mirror upstream's `die("unexpected line: '%s'")` in
			// ls-refs.c:188 — a v2 client that asks for something we
			// neither advertised nor recognise gets a protocol error
			// instead of a silently-empty / silently-altered reply.
			return nil, fmt.Errorf("lsrefs: unexpected line: %q", line)
		}
	}
}
