	closureFetched := false
	fetchClosure := func() error {
		if closureFetched {
			return nil
		}
		if err := sourceService.FetchToStore(ctx, repo.Storer, s.sourceConn, gpDesired, targetRefMap); err != nil {
			if !errors.Is(err, git.NoErrAlreadyUpToDate) {
