package gitsync

import (
	"context"
	"errors"
)

// ProtocolMode controls source-side protocol negotiation.
type ProtocolMode string

// ProtocolAuto negotiates v2 and falls back to v1; ProtocolV1 and ProtocolV2
// pin the choice.
//
// ProtocolV1 is incompatible with SyncPolicy.AllowEmptySource: the unborn-HEAD
// cross-check that policy requires exists only in v2's ls-refs, so pinning v1
// is rejected at the request edge rather than failing every run with an error
// that looks like the source is withholding refs.
const (
	ProtocolAuto ProtocolMode = "auto"
	ProtocolV1   ProtocolMode = "v1"
	ProtocolV2   ProtocolMode = "v2"
)

// OperationMode controls high-level sync semantics.
type OperationMode string

const (
	ModeSync      OperationMode = "sync"
	ModeReplicate OperationMode = "replicate"
)

// Endpoint identifies a remote Git endpoint.
type Endpoint struct {
	URL string `json:"url"`

	// FollowInfoRefsRedirect, when true, rewrites this endpoint's
	// effective host to the final URL returned by /info/refs after
	// HTTP redirects. Subsequent git RPCs (git-upload-pack,
	// git-receive-pack) then target the redirected host directly.
	// Matches vanilla git's smart-HTTP behaviour for discovery-aware
	// servers that 307 /info/refs to a hosting replica.
	FollowInfoRefsRedirect bool `json:"followInfoRefsRedirect,omitempty"`
}

// EndpointAuth carries explicit per-request auth and TLS settings.
// It is resolved through an AuthProvider rather than embedded in Endpoint so
// endpoint identity does not also become the public auth-precedence boundary.
type EndpointAuth struct {
	Username      string `json:"username"`
	Token         string `json:"token"`
	BearerToken   string `json:"bearerToken"`
	SkipTLSVerify bool   `json:"skipTlsVerify"`
}

// EndpointRole identifies whether auth is being resolved for the source or target.
type EndpointRole string

const (
	SourceRole EndpointRole = "source"
	TargetRole EndpointRole = "target"
)

// AuthProvider resolves auth for a request endpoint.
type AuthProvider interface {
	AuthFor(ctx context.Context, endpoint Endpoint, role EndpointRole) (EndpointAuth, error)
}

// StaticAuthProvider returns fixed source and target auth values.
type StaticAuthProvider struct {
	Source EndpointAuth `json:"source"`
	Target EndpointAuth `json:"target"`
}

// AuthFor implements AuthProvider.
func (p StaticAuthProvider) AuthFor(_ context.Context, _ Endpoint, role EndpointRole) (EndpointAuth, error) { //nolint:unparam // implements AuthProvider interface
	if role == TargetRole {
		return p.Target, nil
	}
	return p.Source, nil
}

// RefMapping is an explicit source-to-target ref mapping.
type RefMapping struct {
	Source string `json:"source"`
	Target string `json:"target"`
}

// RefScope constrains which refs a request manages. AllRefs broadens scope
// to every refs/* on the source (branches, tags, notes, pulls, custom
// namespaces) and implies SyncPolicy.IncludeTags. ExcludeRefPrefixes
// subtracts namespaces from auto-discovery (useful for trimming
// refs/pull/* when mirroring open-source GitHub repos under AllRefs);
// explicit Mappings are not subject to it.
type RefScope struct {
	Branches           []string     `json:"branches"`
	Mappings           []RefMapping `json:"mappings"`
	AllRefs            bool         `json:"allRefs,omitempty"`
	ExcludeRefPrefixes []string     `json:"excludeRefPrefixes,omitempty"`
	// IncludeRefPrefixes narrows auto-discovery to the named namespaces: with
	// any set, a ref outside all of them is neither pushed nor pruned.
	// Exclusions still apply within them, and explicit Mappings are exempt
	// from both. Every entry must start with refs/.
	//
	// It narrows the request's scope, not the source ref listing: ls-refs still
	// asks for refs/ under AllRefs, so an empty in-scope set stays
	// distinguishable from a source that advertised nothing (AllowEmptyScope).
	IncludeRefPrefixes []string `json:"includeRefPrefixes,omitempty"`
	// ExcludeRefs subtracts exact ref names from auto-discovery: matched
	// whole (not by prefix), so a caller can reserve a directory-anchor name
	// like refs/heads/entire without also excluding its children
	// (refs/heads/entire/foo). Not applied to explicit Mappings.
	ExcludeRefs []string `json:"excludeRefs,omitempty"`
	// IndependentHistoryRefPrefixes names namespaces whose refs each carry
	// their own history, sharing no commits and next to no objects with any
	// other ref: one orphan history per ref, like per-session checkpoint refs.
	// It does not change which refs are synced or pruned. It only shrinks the
	// haves the relay fetch offers the source: a target ref under one of these
	// prefixes is offered only when the run updates it, as its own old value,
	// because an unchanged one cannot shorten a pack the other refs need.
	// Replicate relays and sync's incremental relay honor it; sync's closure
	// fetch for fast-forward checks and bootstrap keep every target tip.
	//
	// Each entry is matched as a literal string prefix, after trimming
	// surrounding whitespace, against target ref names, which are the names
	// after Mappings apply. No globs, and no implied path boundary: end a
	// namespace with a slash, as in refs/entire/checkpoints/, or it also
	// matches refs/entire/checkpoints-old. Every entry must start with refs/.
	//
	// Naming a namespace whose refs do share history keeps the copy correct
	// and complete, but the source then resends objects the target already
	// holds. The larger pack can exceed a pack size limit (unstable's
	// MaxPackBytes) or a server's request or pack limits, so a transfer that
	// succeeded without the option can fail with it.
	IndependentHistoryRefPrefixes []string `json:"independentHistoryRefPrefixes,omitempty"`
}

// SyncPolicy controls high-level sync behavior. BestEffort downgrades per-ref
// receive-pack rejections to warnings; pack-level failures remain fatal.
//
// ForceWithLease and ForceBlind both allow non-fast-forward branch updates and
// tag retargets; they differ in how the push command's expected-old value is
// set. ForceWithLease sends the target tip captured at session start, so
// receive-pack rejects updates where the target moved during the run (the
// "lease"). ForceBlind sends a zero expected-old, telling receive-pack to
// overwrite regardless of the current target value — matching `git push
// --force` semantics. The two are mutually exclusive.
type SyncPolicy struct {
	Mode           OperationMode `json:"mode"`
	IncludeTags    bool          `json:"includeTags"`
	ForceWithLease bool          `json:"forceWithLease,omitempty"`
	ForceBlind     bool          `json:"forceBlind,omitempty"`
	Prune          bool          `json:"prune"`
	BestEffort     bool          `json:"bestEffort,omitempty"`
	Protocol       ProtocolMode  `json:"protocol"`
	// SourceAssertedEmpty and TargetAssertedEmpty are your authoritative
	// statements that the source and target repositories hold no refs at all
	// — from a repository-state query on each side, not from a ref listing.
	//
	// git-sync cannot determine either and will not guess. Ref hiding is
	// invisible to the client by design, on both legs and independently:
	// uploadpack.hideRefs can reduce a populated source's ls-refs response to
	// an unborn-HEAD line alone, and receive.hideRefs can reduce a populated
	// target's receive-pack advertisement to the bare capabilities^{}
	// sentinel. Neither is distinguishable from a genuinely empty repository.
	// The target case is the sharper one: receive.hideRefs and
	// uploadpack.hideRefs are separate settings, so a ref hidden from the push
	// side is still served to fetchers — a target wrongly judged empty is one
	// whose readers see refs the source does not have.
	//
	// Supply these only from a source of truth that sees past hiding. Without
	// them Replicate reports ErrSourceEmptyUnverified or
	// ErrTargetEmptyUnverified and never claims convergence.
	//
	// They are necessary inputs, never sufficient ones: Replicate
	// independently requires an empty advertisement on each side, an unborn
	// HEAD on the source, no ref names dropped as invalid on either, and no
	// visible target ref, before it will report convergence. Those checks can
	// only refuse — they never turn an absent assertion into a success.
	SourceAssertedEmpty bool `json:"sourceAssertedEmpty,omitempty"`
	TargetAssertedEmpty bool `json:"targetAssertedEmpty,omitempty"`

	// AllowEmptySource opts into treating a verified-empty source as an
	// outcome instead of an error. When source and target are both verified
	// empty (see the asserted-empty fields above) Replicate succeeds with zero
	// plans and ExecutionSummary.Converged set; when the target holds refs the
	// two have diverged and it fails with ErrSourceEmptyTargetPopulated rather
	// than deleting them; when either side's emptiness cannot be established it
	// fails with the matching unverified error.
	//
	// Two requirements, both rejected at the request edge rather than silently
	// ignored:
	//
	//   - Mode must be ModeReplicate. Sync, Bootstrap and Fetch have no
	//     convergence outcome to report.
	//   - RefScope.AllRefs must be set. Under a narrower scope the source ref
	//     listing is itself narrowed, so an empty result says nothing about the
	//     repository as a whole, and the target's refs — which are never
	//     scope-filtered — cannot be judged against a partial view of the
	//     source.
	//
		if err != nil {
			return syncer.Config{}, err
		}
		cfg.Target = syncerEndpoint(*req.Target, targetAuth)
	}
	return cfg, nil
}

func (c *Client) buildSyncConfig(ctx context.Context, req SyncRequest, dryRun bool) (syncer.Config, error) {
	sourceAuth, err := c.authFor(ctx, req.Source, SourceRole)
	if err != nil {
		return syncer.Config{}, err
	}
	targetAuth, err := c.authFor(ctx, req.Target, TargetRole)
	if err != nil {
		return syncer.Config{}, err
	}
	return syncer.Config{
		Source:                        syncerEndpoint(req.Source, sourceAuth),
		Target:                        syncerEndpoint(req.Target, targetAuth),
		BootstrapLogger:               c.bootstrapLogger,
		BootstrapFallbackMaxPackBytes: c.bootstrapFallbackMaxPackBytes,
		HTTPClient:                    c.httpClient,
		Branches:                      append([]string(nil), req.Scope.Branches...),
		Mappings:                      validationMappings(req.Scope.Mappings),
		AllRefs:                       req.Scope.AllRefs,
		ExcludeRefPrefixes:            append([]string(nil), req.Scope.ExcludeRefPrefixes...),
		ExcludeRefs:                   append([]string(nil), req.Scope.ExcludeRefs...),
		IncludeRefPrefixes:            append([]string(nil), req.Scope.IncludeRefPrefixes...),
		IndependentHistoryRefPrefixes: append([]string(nil), req.Scope.IndependentHistoryRefPrefixes...),
		IncludeTags:                   req.Policy.IncludeTags,
		DryRun:                        dryRun,
		ShowStats:                     req.CollectStats,
		Mode:                          string(req.Policy.Mode),
		ForceWithLease:                req.Policy.ForceWithLease,
		ForceBlind:                    req.Policy.ForceBlind,
		Prune:                         req.Policy.Prune,
		BestEffort:                    req.Policy.BestEffort,
		AllowEmptySource:              req.Policy.AllowEmptySource,
		AllowEmptyScope:               req.Policy.AllowEmptyScope,
		SourceAssertedEmpty:           req.Policy.SourceAssertedEmpty,
		TargetAssertedEmpty:           req.Policy.TargetAssertedEmpty,
		ProtocolMode:                  string(req.Policy.Protocol),
		MaterializedMaxObjects:        syncer.DefaultMaterializedMaxObjects,
	}, nil
}

func (c *Client) authFor(ctx context.Context, endpoint Endpoint, role EndpointRole) (EndpointAuth, error) {
	if c.auth == nil {
		return EndpointAuth{}, nil
	}
	auth, err := c.auth.AuthFor(ctx, endpoint, role)
	if err != nil {
		return EndpointAuth{}, fmt.Errorf("resolve auth for %s: %w", role, err)
	}
	return auth, nil
}

func (r SyncRequest) Validate() error {
	return validateSyncFields(r.Source, r.Target, r.Scope, r.Policy)
}

