// ErrNegotiationUnsupported reports a source that cannot answer
// SourceHolds: it does not speak protocol v2 or does not advertise the fetch
// feature wait-for-done.
var ErrNegotiationUnsupported = errors.New("source does not support wait-for-done negotiation")

// SourceHolds asks a protocol v2 source which of haves it holds, in one
// fetch request that names no wants and sends no done. With wait-for-done the
// server answers with its acknowledgments section only and never a pack.
//
// git acknowledges a have it holds unless an earlier have's commit already
// names it as a parent, so an absent hash is reported absent, and a present
// one is reported present unless it is the direct parent of an earlier have.
// Callers that need every hash confirmed, such as a set of tips none of which
// reaches another, get an exact answer; any other caller gets false negatives
// only.
func (s *RefService) SourceHolds(ctx context.Context, conn Conn, haves []plumbing.Hash) (map[plumbing.Hash]bool, error) {
	if s.Protocol != "v2" || !s.V2Caps.FetchSupports("wait-for-done") {
		return nil, ErrNegotiationUnsupported
	}
	sorted := SortedUniqueHashes(haves)
	if len(sorted) == 0 {
		return map[plumbing.Hash]bool{}, nil
	}
	args := make([]string, 0, len(sorted)+1)
	args = append(args, "wait-for-done")
	for _, h := range sorted {
		args = append(args, "have "+h.String())
	}
	body, err := EncodeCommand("fetch", s.V2Caps.RequestCapabilities(), args)
	if err != nil {
		return nil, err
	}
	resp, err := PostRPC(ctx, conn, transport.UploadPackService, body, true, "upload-pack fetch negotiation")
	if err != nil {
		return nil, err
	}
	return decodeAcknowledgments(bytes.NewReader(resp))
}

func decodeAcknowledgments(r *bytes.Reader) (map[plumbing.Hash]bool, error) {
	reader := NewPacketReader(r)
	kind, payload, err := reader.ReadPacket()
	if err != nil {
		return nil, err
	}
	if kind != PacketData || strings.TrimSpace(string(payload)) != "acknowledgments" {
		return nil, fmt.Errorf("negotiation response starts with %q, want acknowledgments", payload)
	}
	held := map[plumbing.Hash]bool{}
	for {
		kind, payload, err := reader.ReadPacket()
		if err != nil {
			return nil, err
		}
		switch kind {
		case PacketFlush:
			return held, nil
		case PacketData:
			line := strings.TrimSpace(string(payload))
			if line == "NAK" {
				continue
			}
			oid, ok := strings.CutPrefix(line, "ACK ")
			if !ok || !plumbing.IsHash(oid) {
				// "ready" would mean a pack follows, which wait-for-done rules out.
				return nil, fmt.Errorf("unexpected acknowledgment line %q", line)
			}
			held[plumbing.NewHash(oid)] = true
		default:
			return nil, fmt.Errorf("unexpected packet type %v in acknowledgments", kind)
		}
	}
}

// Unproven returns the marked hashes not in known, sorted. Reduce relies on
// each marked tip being one the source holds: a marked tip the source lacks
// hides the refs behind it, and the fetch then resends their history.
func (m *MaximalTips) Unproven(known func(plumbing.Hash) bool) []plumbing.Hash {
	if m == nil {
		return nil
	}
	var out []plumbing.Hash
	for _, h := range m.marked {
		if !known(h) {
			out = append(out, h)
		}
	}
	return SortedUniqueHashes(out)
}
