		}
	}
	// No wants and no done: the server must answer with acknowledgments only.
	for _, banned := range []string{"want ", "done\n"} {
		if strings.Contains(req, banned) {
			t.Errorf("request %q carries %q", req, banned)
		}
	}
	if strings.Count(req, "have "+maxA.String()) != 1 {
		t.Errorf("request %q repeats a have", req)
	}
}

func TestSourceHoldsNAK(t *testing.T) {
	svc := v2Service(t, "fetch=wait-for-done")
	conn := &maximalConn{lsRefs: pktBody(t, "acknowledgments", "NAK")}
	held, err := svc.SourceHolds(t.Context(), conn, []plumbing.Hash{maxA})
	if err != nil {
		t.Fatal(err)
	}
	if len(held) != 0 {
		t.Fatalf("held = %v, want none", held)
	}
}

func TestSourceHoldsUnsupported(t *testing.T) {
	for name, svc := range map[string]*RefService{
		"no wait-for-done": v2Service(t, "fetch=shallow filter"),
		"v1":               {Protocol: "v1"},
	} {
		t.Run(name, func(t *testing.T) {
			conn := &maximalConn{}
			if _, err := svc.SourceHolds(t.Context(), conn, []plumbing.Hash{maxA}); !errors.Is(err, ErrNegotiationUnsupported) {
				t.Fatalf("err = %v, want ErrNegotiationUnsupported", err)
			}
			if conn.request != nil {
				t.Fatalf("sent %q to a source that cannot answer", conn.request)
			}
		})
	}
}

// A response that is not an acknowledgments section, or that says a pack
// follows, is refused rather than read as "holds nothing".
func TestSourceHoldsMalformed(t *testing.T) {
	svc := v2Service(t, "fetch=wait-for-done")
	for name, lines := range map[string][]string{
		"packfile": {"packfile"},
		"ready":    {"acknowledgments", "ACK " + maxA.String(), "ready"},
	} {
		t.Run(name, func(t *testing.T) {
			conn := &maximalConn{lsRefs: pktBody(t, lines...)}
			if _, err := svc.SourceHolds(t.Context(), conn, []plumbing.Hash{maxA}); err == nil {
				t.Fatal("err = nil for a malformed negotiation response")
			}
		})
	}
}
